-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":1,"title":"الطباق والمقابلة","passage":"الطباق يجمع لفظين متضادين كـ«الليل والنهار»، والمقابلة ترتب معنيين أو أكثر ثم ما يقابلها في سياق بلاغي. يحدد المتعلم نوع العلاقة من الألفاظ الصحيحة، ولا يعتبر كل كلمتين مختلفتين طباقًا.","question":"أي زوج من الكلمات يتضمن طباقًا؟","correct":"الليل والنهار","wrong":["الكتاب والقلم","الباب والسقف","المعلم والطالب"],"practice":"أنتج طباقًا صحيحًا ومقابلة من إنشائك واشرح وظيفة التضاد في كل سياق.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":2,"title":"فن المقامة","passage":"المقامة جنس نثري يقوم غالبًا على الحكاية ولغة مصنوعة وشخصيات ومواقف قد تتضمن السجع والمفارقة. لا تُنسب قصة مقامة أو قول إلى مؤلف دون النص المحقق. مثال مستقل يلتقي مسافر ببائع يجيد اللعب بالألفاظ، لتدريب المفارقة لا لنقل تراث.","question":"ما الذي يكشف عنصر الحكاية في المقامة؟","correct":"شخصيات وحدث وتحول في الموقف","wrong":["وزن بحر شعري وحده","تعريف معجمي فقط","خلو النص من حدث"],"practice":"اقرأ مقامة موثقة واستخرج سمة سردية وأخرى أسلوبية مع شاهد لكل منهما.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":3,"title":"الجملة التفسيرية","passage":"تأتي الجملة التفسيرية لتوضح معنى كلام سابق، وقد تُقدم بأداة تفسير مثل «أي» في مواضعها. في «أشار إلى المطلوب، أيْ أنْ ينظموا العملَ» يُفهم المقصود من السياق؛ لكن ينبغي مراجعة الإعراب الدقيق للمصدر المؤول بحسب التركيب.","question":"ما الغرض العام من الجملة التفسيرية؟","correct":"توضيح معنى سابق","wrong":["إنشاء نفي بالضرورة","إنهاء الاستفهام فقط","إعراب الفاعل دومًا"],"practice":"اختر مثالًا نحويًا موثقًا لجملة تفسيرية، وميز العبارة المفسِّرة من المفسَّرة.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":4,"title":"فن المناظرة","passage":"تعتمد المناظرة على طرح قضية ومواقف متباينة وحجج وردود وتعقيب، ويجب فصل نقد الفكرة عن نقد الأشخاص. في مثال ضاديوم الأصلي يتناقش طالبان حول زمن القراءة؛ يعرض كل طرف فائدة وتحفظًا ثم يوافقان على تجربة قصيرة.","question":"ما العنصر الأوضح في المناظرة الجيدة؟","correct":"حجج متبادلة وردود على الاعتراض","wrong":["شعار واحد يتكرر","منع السؤال","اتهام المخاطب"],"practice":"صمم مناظرة قصيرة بحجتين متعارضتين وخاتمة منصفة.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":5,"title":"بلاغة الكناية","passage":"الكناية تعبير يقصد معه لازم معنى ظاهر يمكن تصوره، ويحتاج تحديد القرينة ومقام الكلام؛ مثل التعبير عن الكرم بكثرة إعداد الطعام في سياق مناسب. لا يعد كل وصف واقعي كناية من دون دلالة غير مباشرة.","question":"ما الذي يميز الكناية غالبًا؟","correct":"الدلالة غير المباشرة المرتبطة بمعنى العبارة","wrong":["وجود تشبيه بكاف دائمًا","وزن شعري معين","حرف نفي"],"practice":"اختر مثالين للكناية من مرجع بلاغي موثق واشرح معناهما المباشر والمقصود.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":6,"title":"فن أدب الرحلة","passage":"يصف أدب الرحلة مشاهد الأماكن والناس وتجربة المتكلم وربما ملاحظات تاريخية تحتاج تدقيقًا، ولا يصح التعامل مع كل انطباع شخصي بوصفه حقيقة عن مجتمع. نموذج مستقل مسافر يدوّن انطباعًا عن سوق وزمان زيارته.","question":"ما الفارق بين وصف الرحّالة والتعميم العلمي؟","correct":"الوصف يخص تجربة ومكانًا وزمانًا معينًا","wrong":["الوصف يثبت كل الأحوال","كل الأوصاف خاطئة","الزمان غير مهم"],"practice":"اكتب يومية رحلة متخيلة وافصل الملاحظات المباشرة عن التفسيرات الشخصية.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":7,"title":"السجع","passage":"السجع توافق أواخر الفواصل في النثر في أصوات معينة، وقد يخدم الإيقاع والمعنى إذا لم يُضحّ بالوضوح. لا تتحول الجملة إلى شعر لمجرد توافق فواصلها. يفحص المتعلم زوج عبارتين موزونتين في النثر من مصدر معروف.","question":"في أي جنس بلاغي يظهر السجع أساسًا؟","correct":"النثر","wrong":["المعادلات الجبرية","الجداول فقط","الصور الصامتة"],"practice":"ابحث عن مثال نثري سليم للسجع، وفسر العلاقة بين الجرس والمعنى.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":8,"title":"فن المقالة","passage":"تقوم المقالة على فكرة وأطروحة وتنظيم للفقرات وحجج وأمثلة، وقد تكون تفسيرية أو حجاجية أو ذات نزعة أدبية. في نموذج مستقل يكتب طالب مقالًا عن القراءة يشرح فائدة واختبارًا محدودًا ولا يدعي نتيجة اجتماعية عامة.","question":"ما الذي يدعم الأطروحة في المقالة؟","correct":"أمثلة وشواهد مناسبة مع تعليل","wrong":["الإطالة بلا موضوع","إخفاء المصادر","إلغاء الفقرات"],"practice":"اكتب مخطط مقالة بعنوان من اختيارك مع دعوى وحجتين واعتراض.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"9b91a9da-6fbc-48ee-ae03-1ea971ed4951","n":9,"title":"مهارة إلقاء العرض الشفهي","passage":"يحتاج العرض إلى افتتاح يحدد الموضوع، وترتيب ثلاث نقاط وفق وقت الجمهور، وأدلة قابلة للمراجعة، وخاتمة تربط الملاحظات بالفكرة. في مثال مستقل يقدم الطالب عرضًا عن مصادر القراءة ويذكر المرجع لا شعور الثقة فقط.","question":"ما الذي يزيد وضوح العرض ومصداقيته؟","correct":"ترتيب الأفكار وإعلان الشواهد والمصادر","wrong":["تسريع الكلام بلا توقف","تكرار الشعار","إغفال الجمهور"],"practice":"قدّم عرضًا لدقيقتين وقيم صوتك وتسلسل الحجج وحدود الدليل.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":1,"title":"بلاغة الاستعارة","passage":"تقوم الاستعارة على علاقة المشابهة مع حذف أحد طرفي التشبيه وقرينة تبعد المعنى الحرفي، مثل «ابتسم الصباح» حيث شُخّص الصباح. جودة الاستعارة لا تثبت باسمها وحده بل بملاءمتها للجو والمعنى.","question":"ما الصورة في «ابتسم الصباح»؟","correct":"استعارة تشخص الصباح","wrong":["طباق","جناس","مضاف إليه"],"practice":"أنشئ استعارة مكنية وأخرى تصريحية واشرح القرينة وأثر كل صورة.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":2,"title":"السيف أصدق أنباء","passage":"تحتاج قراءة «السيف أصدق أنباء» إلى الأبيات الصحيحة والسياق قبل نسبة رأي تاريخي أو معركة أو اقتباس إلى أبي تمام. يمكن تحليل مقابلة الفعل والخبر من النص الحقيقي، لكن تمرين ضاديوم لا يروي معركة ولا يصنع شعرًا.","question":"ما الدليل على الوظيفة البلاغية في البيت المقرر؟","correct":"الأبيات الصحيحة وسياق المخاطب","wrong":["حكاية مخترعة","العنوان وحده","تخمين اسم المكان"],"practice":"استخرج شاهدًا صحيحًا لأسلوب المقابلة أو الصورة من القصيدة مع توثيق المصدر.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":3,"title":"الجملة الاعتراضية","passage":"قد تقع الجملة الاعتراضية بين أجزاء تركيب متصل لإضافة دعاء أو تعليق دون أن تكون ركنًا في الإسناد الأصلي. في «العلمُ — حفظك الله — نافعٌ» لا تتغير صلة المبتدأ بالخبر عند حذف الجملة المعترضة.","question":"ما موقع «حفظك الله» في المثال؟","correct":"جملة اعتراضية","wrong":["فاعل خبر المبتدأ","مضاف إليه","نعت لازم"],"practice":"صغ جملتين فيهما اعتراض، وبيّن موضعه وعلاقة الجمل قبل وبعد الحذف.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":4,"title":"زارت عليّ","passage":"لا يبيّن عنوان «زارت عليّ» القائل أو نوع الزائر أو الحادثة، لذا يحتاج التفسير نصًا أدبيًا صحيحًا موثقًا. في قصة أصلية يزور زميل صديقه على غير موعد ويساعده على حل مشكلة؛ هذا تدريب سردي لا بيت من القصيدة.","question":"ما الذي يحدد عاطفة المتكلم في نص أدبي؟","correct":"قرائن الألفاظ والسياق الموثق","wrong":["العنوان وحده","إضافة بيت مولّد","الوزن فقط"],"practice":"استخرج شاهدين صحيحين من النص المقرر يبينان المتكلم والمخاطب والعاطفة.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":5,"title":"بحر المجتث","passage":"من صور البحر المجتث المشهورة نسق «مستفعلن فاعلاتن» في كل شطر في صورته المجزوءة الشائعة، مع تغييرات عروضية تحتاج مراجعة مرجع مختص. لا يجوز استنتاج الوزن من القافية وحدها.","question":"ما التفعيلة التي تسبق «فاعلاتن» في النسق المدروس للمجتث؟","correct":"مستفعلن","wrong":["فعولن","متفاعلن","مفاعلتن"],"practice":"ابحث عن بيت موثق على المجتث وقطعه وحدد صورته المستعملة.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":6,"title":"واحر قلباه!","passage":"قراءة «واحر قلباه» للمتنبي تستلزم الأبيات الصحيحة ومقام الخطاب قبل استنتاج المخاطب أو المشاعر الدقيقة. قد تؤدي صيغة الندبة إلى إبراز الانفعال؛ لكن لا تُنسب عبارة من إنشاء ضاديوم إلى الديوان.","question":"ما الغرض الذي قد تبرزه صيغة الندبة في العنوان؟","correct":"شدة الانفعال حسب السياق","wrong":["تعيين زمان الرحلة","نفي وقوع الحدث","إثبات قافية غير معروفة"],"practice":"حدد شاهداً موثقًا من القصيدة يوضح موقف المتكلم ونبرة الخطاب.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":7,"title":"بحر الهزج","passage":"يشيع في درس بحر الهزج نسق «مفاعيلن مفاعيلن» في الشطر في صوره المجزوءة الشائعة، وقد تدخل عليه تغييرات عروضية. يعتمد تحديد البحر على الكتابة الصوتية والتقطيع الصحيح لا عدد الحروف.","question":"ما التفعيلة الأساسية للهزج؟","correct":"مفاعيلن","wrong":["فاعلاتن","متفاعلن","مستفعلن"],"practice":"اختر بيتًا صحيح المصدر على الهزج وقطعه كتابة عروضية مع ذكر الزحافات إن وجدت.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":8,"title":"ونحن ركب من الأشراف منتظم","passage":"يجب الرجوع إلى النص الذي يتضمن عبارة «ونحن ركب من الأشراف منتظم» للتحقق من نسبته وفهم معنى الجماعة والسياق البلاغي، ولا يصح إضافة أبيات أو تاريخ مناسبة من الخيال. مثال أصلي يصف فريقًا يعتز بتعاونه دون نسبته للشعر القديم.","question":"ما الشرط لتفسير الفخر أو الاعتزاز في القصيدة؟","correct":"شاهد نصي موثق مع سياقه","wrong":["اسم كلمة «ركب» وحده","توليد سبب نزول","اختلاق أسماء أفراد"],"practice":"استخرج من الأبيات الصحيحة لفظًا يحدد المخاطب أو الجماعة واشرح وظيفته.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":9,"title":"بحر المقتضب","passage":"بحر المقتضب من البحور قليلة الاستعمال، ومن أنساق صورته المجزوءة «مفعولاتُ مستفعلن» مع ما يطرأ من تغيير وتفسير عروضيين، لذا ينبغي الرجوع إلى كتاب عروض معتمد قبل الحكم على مثال.","question":"ما التفعيلة الأولى في نسق مجزوء المقتضب المدرسي المذكور؟","correct":"مفعولاتُ","wrong":["فعولن","متفاعلن","فاعلاتن"],"practice":"اعتمد شطرًا صحيحًا من كتاب عروض وقطعه مع توضيح الصورة المستعملة دون اختلاق بيت.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"5cfad72a-e219-4300-8158-179b4c50b0ad","n":10,"title":"مهارة إنتاج إنشاء أدبي حول نص شعري","passage":"ينطلق الإنشاء حول قصيدة من أطروحة محددة وتحليل بيت أو صورة من النص الموثق ثم مناقشة أثرها في الغرض والبناء وخاتمة. لا يكفي إعادة سرد الأبيات أو استبدالها ببيت مولد.","question":"ما الذي يدعم الإنشاء الأدبي حول قصيدة؟","correct":"شاهد صحيح وتحليل وظيفته","wrong":["تلخيص عنوان فقط","اقتباس مختلق","إلغاء السياق"],"practice":"اكتب مقالًا من ثلاث فقرات عن نص شعري موثق يتضمن فكرة وشاهدين وتحليلًا.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":1,"title":"ما لي بدار خلت من أهلها شغل","passage":"عنوان «ما لي بدار خلت من أهلها شغل» لا يثبت السياق أو القائل، ويحتاج النص الصحيح لاستخراج علاقة الدار بالذكرى أو الرفض. مثال مستقل يرى فيه راو منزلًا فارغًا فيتساءل عن معنى المكان بعد رحيل ساكنيه، وليس من القصيدة.","question":"ما الذي يثبت دلالة الدار في القصيدة؟","correct":"الأبيات الموثقة وسياق المتكلم","wrong":["تخمين من العنوان","رواية مؤلفة","عدد كلمات الشطر"],"practice":"وثق صورة للدار من النص الأصلي وقارنها بمشهد نثري من إنشائك.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":2,"title":"الجملة الواقعة اسما أو خبرا لناسخ","passage":"قد يقع المصدر المؤول في موقع اسم ناسخ ضمن شروط تركيبية محددة، كما يمكن أن تقع جملة فعلية خبرًا لناسخ مثل «أصبح الطفلُ يقرأُ». يُحدد الموقع بالإعراب وعلاقة العامل، ولا يصح اعتبار كل فعل بعد ناسخ خبرًا دون تحليل.","question":"ما وظيفة «يقرأ» في «أصبح الطفل يقرأ»؟","correct":"جملة فعلية في محل نصب خبر أصبح","wrong":["فاعل أصبح","اسم مجرور","جواب قسم"],"practice":"راجع مثالين صحيحين لخبر الناسخ الجملة، ثم مثالًا لمصدر مؤول واقع اسمًا لناسخ.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":3,"title":"إذا ما خلوت الدهر يوما","passage":"تستلزم قصيدة «إذا ما خلوت الدهر يوما» النص الصحيح قبل تحليل الشرط والنصيحة أو نسبة مضمون إلى شاعر بعينه. مثال مستقل: يراجع شخص عمله عندما يكون وحده ويفكر في مسؤولية قراره؛ يعرض مفهوم المحاسبة لا نص التراث.","question":"ما المصدر السليم لفهم مضمون القصيدة؟","correct":"شواهد صحيحة من النص المقرر","wrong":["عنوان وحده","مقولة ملفقة","حكاية بلا مصدر"],"practice":"استخرج أسلوب شرط موثقًا من القصيدة المقررة وناقش علاقته بفكرتها.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":4,"title":"الجملة الواقعة في محل جر مضافا إليها","passage":"قد تقع الجملة في محل جر بالإضافة بعد ظروف مثل «حين» في «جلستُ حينَ بدأَ الدرسُ»، حيث تأتي جملة «بدأ الدرس» مضافة إلى الظرف بحسب التحليل النحوي المعروف. نراعي اللفظ والعامل والسياق.","question":"ما موقع «بدأ الدرس» بعد «حين»؟","correct":"في محل جر بالإضافة","wrong":["فاعل مرفوع","مفعول به منصوب","اسم إن"],"practice":"أعرب جملتين تحتويان ظروفًا مضافة إلى جمل مع تمييز المتعلق.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":5,"title":"كذا فليجل الخطب","passage":"لا يجوز أن يُنسب إلى قصيدة «كذا فليجل الخطب» نص غير محقق أو تفسير تاريخي مخترع. في مثال أصلي يشعر فريق بحزن على فقد معلم فيكتب رسالة تقدير، وهو مشهد مستقل لا يمثل الشعر.","question":"ما الشرط لتحليل الرثاء في قصيدة مقررة؟","correct":"الأبيات الصحيحة وشواهد العاطفة","wrong":["عنوان فقط","حكاية لم تقع","تخمين القافية"],"practice":"استخرج لفظين صحيحين من القصيدة يبرزان الحزن أو التقدير، مع تفسير.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":6,"title":"بلاغة التشبيه","passage":"تقوم صورة التشبيه على طرفين ووجه شبه قد يذكر أو يحذف وأداة قد تذكر أو تحذف. في «التعاونُ كالبناءِ المتينِ» يشبه التعاون بالبناء من حيث ترابط الأجزاء؛ تحدد ملاءمة الوجه من السياق.","question":"ما المشبه به في «التعاون كالبناء المتين»؟","correct":"البناء المتين","wrong":["التعاون","الكاف","ترابط"],"practice":"أنشئ تشبيهًا تام الأركان وآخر حذفت أداته، وبين أثرهما.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":7,"title":"أيها الساقي إليك المشتكى","passage":"يحتاج نص «أيها الساقي إليك المشتكى» إلى نسخة صحيحة للتحقق من المتكلم والمخاطب والصورة والغرض، ولا يفترض من النداء المعنى الحرفي أو تفاصيل مجلس مجهول. مثال تدريبي يناجي فيه متكلم مخاطبًا طلبًا للمساندة دون أن يمثل النص.","question":"ما الذي يحدد الغرض البلاغي للنداء هنا؟","correct":"الأبيات الصحيحة والمقام","wrong":["اسم المخاطب وحده","تخمين المصدر","توليد بيت"],"practice":"حلل نداءً موثقًا من النص المقرر مع تفسير نبرة الشكوى.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"99a25e97-b4a5-4b62-b1a6-cb3bbbc90683","n":8,"title":"مهارة التحليل والتعليق","passage":"التحليل يفكك عناصر النص ويعزو الأحكام إلى الشواهد، والتعليق يناقش قيمته أو حدوده من منظور معلل. في مثال مستقل يقارن طالب وجهتي نظر في تقرير ويبين أين تتوفر الأدلة وأين يغلب الانطباع.","question":"ما الذي يميز التعليق النقدي من إعادة الشرح؟","correct":"موقف معلل يستند إلى شواهد","wrong":["تكرار النص","تغيير اسم الكاتب","إلغاء الأدلة"],"practice":"اكتب تحليلًا ثم تعليقًا على فقرة موثقة مع فصل الوصف عن الحكم.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"4e771021-c289-4cfb-ac36-bd816319ad15","n":1,"title":"تأكيد المدح بما يشبه الذم","passage":"في هذا الأسلوب يتوقع القارئ معنى ذم بعد أداة استثناء أو نحوها ثم يأتي وصف مدحي يعزز الإشادة، أو العكس في الأسلوب المقابل. يحتاج التطبيق إلى تركيب بلاغي صحيح، لا مجرد الجمع بين مدح وذم في فقرة واحدة.","question":"ما الغاية البلاغية الأساسية لهذا الأسلوب؟","correct":"تقوية المدح بمفاجأة التوقع","wrong":["إلغاء كل مدح","ذكر تضاد عشوائي","استفهام عن زمن"],"practice":"استخرج مثالًا موثقًا لتأكيد المدح بما يشبه الذم واشرح موضع انتقال التوقع.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"4e771021-c289-4cfb-ac36-bd816319ad15","n":2,"title":"اللف والنشر","passage":"يقوم اللف والنشر على ذكر أمور متعددة ثم ذكر ما يتعلق بكل منها مع ترتيب أو دون ترتيب معلوم في بعض الصور. يحتاج التحليل مضاهاة العلاقات بين العناصر لا مجرد عد الكلمات.","question":"ما الذي يجب مطابقته في اللف والنشر؟","correct":"كل عنصر بما يخصه من عناصر النشر","wrong":["القافية فقط","أول حرف من الأسماء","حركات الإعراب وحدها"],"practice":"اكتب مثالًا بسيطًا للّف والنشر المرتب مع جدول يربط العناصر.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"4e771021-c289-4cfb-ac36-bd816319ad15","n":3,"title":"أغراض الشعر عند القرطاجني","passage":"لا يمكن نقل تصنيف أغراض الشعر عند حازم القرطاجني أو نسب تعريف إلى «منهاج البلغاء» دون قراءة نص نقدي محقق. تدريب مستقل يميز بين غرض المدح والرثاء والنصح بناءً على شواهد شعرية صحيحة، ولا يزعم تمثيل تقسيم المؤلف.","question":"ما الطريق الصحيح لذكر رأي القرطاجني في الأغراض؟","correct":"الاستشهاد بمصدره النقدي المحقق","wrong":["اختراع قائمة","الاعتماد على عنوان الدرس","النقل بلا توثيق"],"practice":"استخرج من مرجع نقدي موثوق تصنيفًا واحدًا للقرطاجني مع بيان ألفاظه الأصلية.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"4e771021-c289-4cfb-ac36-bd816319ad15","n":4,"title":"أسلوب الحكيم","passage":"في أسلوب الحكيم يحول المتكلم الإجابة أو التوجيه إلى ما يراه أولى بالمقام، مع صلة مناسبة بالسؤال أو المخاطب. لا يعد كل خروج عن الموضوع أسلوب حكيم إذا خلا من هدف بلاغي يمكن تفسيره.","question":"ما علامة أسلوب الحكيم في موقف حواري مناسب؟","correct":"توجيه الكلام إلى ما هو أولى بالنفع","wrong":["التهرب العشوائي","تكرار السؤال فقط","انقطاع الصلة بلا غرض"],"practice":"أنشئ حوارًا قصيرًا يوضح أسلوب الحكيم واشرح الغرض من العدول عن الجواب المتوقع.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"4e771021-c289-4cfb-ac36-bd816319ad15","n":5,"title":"صناعة الكلام","passage":"يمكن أن تتعلق «صناعة الكلام» بتقنيات اختيار اللفظ والترتيب والبلاغة أو بسياق نقدي خاص حسب النص المقرر؛ ينبغي الرجوع إلى المصدر قبل نسبة اصطلاح محدد لكاتب. مثال مستقل يراجع طالب فقرة فيحذف الحشو ويقدم الدليل قبل الخلاصة.","question":"ما الذي يحسن صناعة فقرة حجاجية في المثال؟","correct":"ترتيب الدليل وحذف الحشو","wrong":["زيادة التكرار","إخفاء القضية","تقديم نتيجة بلا تعليل"],"practice":"حلل فقرة من إنشاءك قبل التحرير وبعده مع تفسير ثلاثة تغييرات أسلوبية.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"4e771021-c289-4cfb-ac36-bd816319ad15","n":6,"title":"في ترجيح النثر على الشعر","passage":"تمثل المفاضلة بين النثر والشعر مسألة نقدية تختلف معاييرها وأغراضها؛ لا يمكن نسبة تفضيل أو حجته إلى كاتب دون النص الصحيح. في تجربة مستقلة يكتب طالب فكرة مرة في مقالة ومرة في مقطع شعري ويقارن وسيلة التعبير لا قيمة الجنس بإطلاق.","question":"ما معيار المفاضلة المنصفة بين الجنسين؟","correct":"تحديد الغرض والشواهد والوظيفة الفنية","wrong":["القول إن أحدهما أفضل دائمًا","الحكم بطول النص","اختلاق رأي مؤلف"],"practice":"وثق فقرة نقدية تقارن النثر والشعر، ثم قدم ردًا معللًا مع شاهدين صحيحين.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"},{"cid":"6145f014-04f2-4dee-a1b0-d4d244b11623","unit":"4e771021-c289-4cfb-ac36-bd816319ad15","n":7,"title":"مهارة كتابة إنشاء أدبي حول نص حجاجي","passage":"يحدد الكاتب الأطروحة والحجج والاعتراض وطريقة الرد في النص المقروء ثم يقدم قراءة نقدية لشاهد صحيح المصدر. لا يساوي التحليل تلخيص كل جملة، ولا يقوم على انطباع غير مسند.","question":"ما الذي يثبت الأطروحة الحجاجية في الإنشاء؟","correct":"حجج وشواهد صحيحة مع تفسير","wrong":["تكرار العنوان","اختلاق نص","إلغاء الاعتراض"],"practice":"اكتب إنشاء من ثلاث فقرات حول نص حجاجي موثق، مع شاهد وموقف نقدي.","old":"DADYOOM_MR_G12_LITERARY_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id=r.cid
    AND g.grade_number=12 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G12_ARTS_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G12_ARTS_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G12_ARTS_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G12_ARTS_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G12_ARTS_ORIGINAL_34_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G12_ARTS_ORIGINAL_34_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G12_ARTS_ORIGINAL_34_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G12_ARTS_ORIGINAL_34_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G12_ARTS_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;